run ResConv1Test vtaResConv1TestBundle vtaResConv1TestInput.bin vtaResConv1TestGolden.bin
run ResConv2Test vtaResConv2TestBundle vtaResConv2TestInput.bin vtaResConv2TestGolden.bin
